<div class="event-folder-panel"><div class="panel-header"><div><h3><i class="fas fa-folder-tree"></i> Department Event Folders</h3><p class="help">Events are automatically filed under the department selected during creation.</p></div></div><div class="event-folder-grid"><a class="event-folder <?=($folder==='all'||$folder==='')?'active':''?>" href="index.php?folder=all"><i class="fas fa-box-archive"></i><span><strong>All Events</strong><small><?=(int)$sum['total']?> event<?=((int)$sum['total']===1?'':'s')?></small></span></a><a class="event-folder <?=$folder==='school'?'active':''?>" href="index.php?folder=school"><i class="fas fa-school"></i><span><strong>School-wide</strong><small><?=$schoolEventCount?> event<?=$schoolEventCount===1?'':'s'?></small></span></a><?php foreach($departmentRows as $department):?><a class="event-folder <?=(string)$folder===(string)$department['id']?'active':''?>" href="index.php?folder=<?=(int)$department['id']?>"><i class="fas fa-folder<?=((int)$department['ongoing_count']>0)?'-open':''?>"></i><span><strong><?=h($department['code'])?></strong><small><?=h($department['name'])?> · <?=(int)$department['event_count']?> event<?=((int)$department['event_count']===1?'':'s')?></small></span><?php if((int)$department['ongoing_count']>0):?><b><?=(int)$department['ongoing_count']?> live</b><?php endif;?></a><?php endforeach;?></div><form method="post" class="folder-create-form"><?=csrf_field()?><input type="hidden" name="action" value="create_folder"><input type="hidden" name="folder" value="<?=h((string)$folder)?>"><div class="field"><label>New folder code</label><input name="department_code" maxlength="20" placeholder="CCS" required></div><div class="field"><label>Department name</label><input name="department_name" maxlength="180" placeholder="College of Computer Studies" required></div><button class="btn secondary"><i class="fas fa-folder-plus"></i> Create Folder</button></form></div>
<div class="stats-grid"><div class="stat-card elections"><div class="stat-icon"><i class="fas fa-layer-group"></i></div><div><div class="stat-number"><?=(int)$sum['total']?></div><div class="stat-label">All Events</div></div></div><div class="stat-card voters"><div class="stat-icon"><i class="fas fa-door-open"></i></div><div><div class="stat-number"><?=(int)$sum['open']?></div><div class="stat-label">Registration Open</div></div></div><div class="stat-card votes"><div class="stat-icon"><i class="fas fa-circle"></i></div><div><div class="stat-number"><?=(int)$sum['ongoing']?></div><div class="stat-label">Ongoing</div></div></div><div class="stat-card turnout"><div class="stat-icon"><i class="fas fa-flag-checkered"></i></div><div><div class="stat-number"><?=(int)$sum['completed']?></div><div class="stat-label">Completed</div></div></div></div>
<?php if($showForm):$v=$edit?:[];$selectedDepartment=$_POST['department_id']??$v['department_id']??(ctype_digit((string)$folder)?$folder:'');?><div class="card"><h3><?=$edit?'Edit event':'Create event'?></h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><input type="hidden" name="folder" value="<?=h((string)$folder)?>"><div class="field"><label>Department folder</label><select name="department_id"><option value="">School-wide Events</option><?php foreach($departmentRows as $department):?><option value="<?=(int)$department['id']?>" <?=(string)$selectedDepartment===(string)$department['id']?'selected':''?>><?=h($department['code'].' — '.$department['name'])?></option><?php endforeach;?></select><p class="help">The event will automatically appear inside this folder.</p></div><div class="field"><label>Event title</label><input name="title" maxlength="180" required value="<?=h($_POST['title']??$v['title']??'')?>"></div><div class="field full"><label>Description / instructions</label><textarea name="description"><?=h($_POST['description']??$v['description']??'')?></textarea></div><div class="field full"><label>Venue</label><input name="venue" maxlength="220" value="<?=h($_POST['venue']??$v['venue']??'')?>"></div><div class="field"><label>Starts at</label><input type="datetime-local" name="start_at" required value="<?=h(isset($v['start_at'])?date('Y-m-d\TH:i',strtotime($v['start_at'])):'')?>"></div><div class="field"><label>Ends at</label><input type="datetime-local" name="end_at" required value="<?=h(isset($v['end_at'])?date('Y-m-d\TH:i',strtotime($v['end_at'])):'')?>"></div><div class="field"><label>Registration deadline</label><input type="datetime-local" name="registration_deadline" value="<?=h(!empty($v['registration_deadline'])?date('Y-m-d\TH:i',strtotime($v['registration_deadline'])):'')?>"></div><div class="field"><label>Capacity</label><input type="number" min="1" name="capacity" placeholder="Unlimited" value="<?=h($v['capacity']??'')?>"></div><div class="field"><label>Status</label><select name="status"><?php foreach(['draft'=>'Draft','open'=>'Registration open','ongoing'=>'Ongoing / check-in open','completed'=>'Completed','cancelled'=>'Cancelled'] as $key=>$label):?><option value="<?=$key?>" <?=($_POST['status']??$v['status']??'draft')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label>Attendee access</label><label class="choice"><input type="checkbox" name="allow_self_checkin" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['allow_self_checkin']):($v['allow_self_checkin']??true))?'checked':''?>> Allow self check-in</label></div><div class="field full actions"><button class="btn">Save event</button><a class="btn secondary" href="index.php?folder=<?=h(urlencode((string)$folder))?>">Cancel</a></div></form></div><?php endif;?>
<div class="card"><div class="panel-header"><div><h3><i class="fas fa-folder-open"></i> <?=h($activeFolderName)?></h3><p class="help">Only events filed in the selected folder are shown below.</p></div></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Department Folder</th><th>Schedule</th><th>Status</th><th>Attendance</th><th>Actions</th></tr></thead><tbody><?php if($rows):while($e=pg_fetch_assoc($rows)):$pct=(int)$e['registered']?round((int)$e['present']/(int)$e['registered']*100):0;?><tr><td><strong><?=h($e['title'])?></strong><div class="help"><i class="fas fa-location-dot"></i> <?=h($e['venue']?:'Venue TBA')?><?= $e['capacity']?' · Capacity '.(int)$e['capacity']:'' ?></div></td><td><span class="folder-label"><i class="fas fa-folder"></i> <?=h($e['department_code']?:'School-wide')?></span><div class="help"><?=h($e['department_name']?:'Shared institutional events')?></div></td><td><?=h(date('M j, Y g:i A',strtotime($e['start_at'])))?><div class="help">to <?=h(date('M j, Y g:i A',strtotime($e['end_at'])))?></div></td><td><span class="badge <?=h($e['status'])?>"><?=h(ucfirst($e['status']))?></span></td><td><strong><?=(int)$e['present']?> / <?=(int)$e['registered']?></strong><div class="help"><?=$pct?>% attendance</div></td><td><div class="actions"><a class="btn small secondary" href="?edit=<?=(int)$e['id']?>&amp;folder=<?=h(urlencode((string)$folder))?>">Edit</a><a class="btn small secondary" href="details.php?id=<?=(int)$e['id']?>">Sessions</a><a class="btn small secondary" href="../attendees/index.php?event_id=<?=(int)$e['id']?>">Register</a><a class="btn small" href="../attendance/index.php?event_id=<?=(int)$e['id']?>">Check-in</a><a class="btn small secondary" href="../reports/index.php?event_id=<?=(int)$e['id']?>">Report</a><a class="btn small danger" href="../data/index.php"><i class="fas fa-file-export"></i> Export / Delete</a></div></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="6" class="empty">This folder has no events yet. Create an event here to get started.</td></tr><?php endif;?></tbody></table></div></div>
